-- Expand European first/second-tier aliases and keep explicit lower-tier exclusions.
CREATE OR REPLACE FUNCTION public.moneyball_is_european_top_two_league(p_country text, p_competition text)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path TO '' AS $function$
WITH n AS (SELECT regexp_replace(translate(lower(coalesce(p_competition,'')), 'áéíóúüñç', 'aeiouunc'), '[^a-z0-9]+', ' ', 'g') AS comp)
SELECT (
 lower(coalesce(p_country,'')) = ANY (ARRAY['albania','andorra','armenia','austria','azerbaijan','belarus','belgium','bosnia and herzegovina','bulgaria','croatia','cyprus','czechia','czech republic','denmark','england','estonia','faroe islands','finland','france','georgia','germany','gibraltar','greece','hungary','iceland','ireland','isle of man','italy','kazakhstan','kosovo','latvia','liechtenstein','lithuania','luxembourg','malta','moldova','monaco','montenegro','netherlands','north macedonia','northern ireland','norway','poland','portugal','romania','russia','san marino','scotland','serbia','slovakia','slovenia','spain','sweden','switzerland','turkey','türkiye','ukraine','wales','united kingdom','uk','alb','and','arm','aut','aze','blr','bel','bih','bul','cro','cyp','cze','dnk','eng','est','fro','fin','fra','geo','deu','ger','gib','grc','gre','hun','isl','irl','ita','kaz','kos','lva','lie','ltu','lux','mlt','mda','mne','nld','mkd','nir','nor','pol','prt','por','rou','rus','smr','sco','srb','svk','svn','esp','swe','che','sui','tur','ukr','wal','gbr','uk']) OR n.comp ~* '^uefa nations league'
) AND n.comp <> ''
AND n.comp !~* '(u(15|16|17|18|19|20|21|23)|under ?(15|16|17|18|19|20|21|23)|youth|juniors?|academy|juvenil|jugend|reserves?|b team|cup|copa|trophy|play offs?|women|woman|female|frauen|damen|feminine|femminile|femenina|ladies|girls)'
AND n.comp !~* '(druha liga|(^| )(3|4|5|6|7|8|9|iii|iv|v|vi) (liga|league|division|div|bundesliga|serie|snl|hnl|federal|federation)|third|fourth|fifth|regional|regionalliga|oberliga|national league north|national league south|non league)'
AND (n.comp ~* '^uefa nations league' OR n.comp ~* '(premier league|premiership|championship|super league 2|super league|superliga|super lig|pro league|jupiler pro league|challenger pro league|bundesliga|austrian 2 liga|2 bundesliga|ligue 1|ligue 2|serie a|serie b|la liga|laliga|primera division|segunda division|segunda liga|segunda divisao|liga portugal 2|liga portugal|eredivisie|eerste divisie|keuken kampioen divisie|primeira liga|ekstraklasa|i liga|1 lig|2 lig|1 liga|2 liga|liga i|liga ii|liga 1|liga 2|liga e pare|prva liga|first league|second league|fnl|first division|second division|division 1|division 2|div 1|div 2|1st division|2nd division|1st league|2nd league|a lyga|i lyga|virsliga|meistriliiga|esiliiga|veikkausliiga|ykkosliiga|allsvenskan|superettan|eliteserien|obos ligaen|1 divisjon|premier division|league of ireland premier|league of ireland first|scottish championship|challenge league|tff first league|nb i|nb ii|nemzeti bajnoksag i|nemzeti bajnoksag ii|kategoria superiore|kategoria e pare|premyer liqa|i liqa|1 deild|cymru premier|cymru north|cymru south|erovnuli liga 2|first nl|prva nl|2 snl|first professional football league|second professional football league|bulgarian second league|first division a|first division b|1 division|2 division|divizia nationala|divizia a)')
FROM n;
$function$;
